package com.example.starter.plan.model;

import java.math.BigDecimal;

/**
 * 列车应急制动档案。
 *
 * @param id          主键
 * @param trainNo     列车编号，全局唯一
 * @param reactionT   反应时间 t，秒，正十进制、最多 3 位小数
 * @param baseDecelA  基础减速度 a，米每平方秒，正十进制、最多 3 位小数
 * @param version     配置版本，创建为 1，每次成功修改加一
 */
public record TrainProfile(long id, String trainNo, BigDecimal reactionT, BigDecimal baseDecelA,
                           int version) {
}

package com.example.starter.plan.model;

import java.math.BigDecimal;

/**
 * 区段防护档案。
 *
 * @param id        主键
 * @param sectionId 区段 ID，全局唯一
 * @param protectD  防护距离 d，米，正十进制、最多 3 位小数
 * @param version   配置版本，创建为 1，每次成功修改加一
 */
public record SectionProfile(long id, String sectionId, BigDecimal protectD, int version) {
}

package com.example.starter.plan.model;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 计划内一条区段占用，区间左闭右开 [startUtc, endUtc)。
 *
 * @param id        主键
 * @param planId    所属计划 id
 * @param seq       计划内序号，保持提交顺序
 * @param trainNo   列车编号
 * @param sectionId 区段 ID
 * @param startUtc  占用开始时刻（含），UTC
 * @param endUtc    占用结束时刻（不含），UTC，必须晚于 startUtc
 * @param speedV    占用速度 v，米每秒，非负、最多 3 位小数；null 表示无速度占用，
 *                  不适用制动包络检查，不能补零冒充
 */
public record Occupancy(long id, long planId, int seq, String trainNo, String sectionId,
                        Instant startUtc, Instant endUtc, BigDecimal speedV) {
}

