private List<EnvelopeSnapshot> checkEnvelope(DayPlan plan, List<Occupancy> occupancies, long now) {
    List<EnvelopeSnapshot> snapshots = new ArrayList<>();
    List<Map<String, Object>> violations = new ArrayList<>();
    for (Occupancy o : occupancies) {
        if (o.speedV() == null) continue; // 无速度占用不适用
        TrainProfile train = profileRepo.findTrainProfile(o.trainNo())
            .orElseThrow(() -> new ApiException(NOT_FOUND, "TRAIN_PROFILE_NOT_FOUND", ...));
        SectionProfile section = profileRepo.findSectionProfile(o.sectionId())
            .orElseThrow(() -> new ApiException(NOT_FOUND, "SECTION_PROFILE_NOT_FOUND", ...));
        BigDecimal lhs = EnvelopeMath.leftValue(o.speedV(), train.reactionT(), train.baseDecelA());
        BigDecimal rhs = EnvelopeMath.rightValue(train.baseDecelA(), section.protectD());
        if (lhs.compareTo(rhs) > 0) { violations.add(detail...); }
        else snapshots.add(new EnvelopeSnapshot(0, plan.id(), o.id(), ...now));
    }
    if (!violations.isEmpty()) throw new ApiException(422, "ENVELOPE_EXCEEDED", ...);
    return snapshots;
}
