        mvc.perform(put("/api/v1/train-profiles/{trainNo}", key("G"))
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(trainUpdateBody(key("REQ"), "op-1", "1.000", "2.000", 1)))
                .andExpect(status().isNotFound());
